import{_ as a,o as t,c as r,an as o}from"./chunks/framework.DAsE5xAf.js";const h=JSON.parse('{"title":"Benchmarking","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks/results.md","filePath":"benchmarks/results.md","lastUpdated":null}'),i={name:"benchmarks/results.md"};function n(s,e,l,c,p,m){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="Benchmarking" tabindex="-1">Benchmarking <a class="header-anchor" href="#Benchmarking" aria-label="Permalink to &quot;Benchmarking {#Benchmarking}&quot;">​</a></h1><p>The code and configurations are in our <a href="https://github.com/JuliaLegate/benchmarking" target="_blank" rel="noreferrer">benchmarking repository</a>. Run <code>./run_all.sh</code> from the repository root, or read its <a href="https://github.com/JuliaLegate/benchmarking#readme" target="_blank" rel="noreferrer">README</a> for setup and individual benchmarks.</p><h2 id="Package-Integrations" tabindex="-1">Package Integrations <a class="header-anchor" href="#Package-Integrations" aria-label="Permalink to &quot;Package Integrations {#Package-Integrations}&quot;">​</a></h2><p>The <a href="./../examples/krylov">Krylov.jl CG</a> and <a href="./../examples/ordinarydiffeq">OrdinaryDiffEq.jl heat diffusion</a> benchmarks compare cuNumeric.jl, CUDA.jl, and Dagger.jl arrays. The left panels vary the problem size on one GPU. The right panels show weak scaling, where cuNumeric.jl keeps solve and step times nearly constant as the GPU count grows.</p><p>Lower times are better. <object data="../images/benchmarks/composability.pdf" type="application/pdf" style="width:100%;aspect-ratio:475 / 464;" aria-label="Krylov.jl CG solve times and OrdinaryDiffEq.jl heat diffusion step times on one and multiple GPUs."><a href="../images/benchmarks/composability.pdf">Krylov.jl CG solve times and OrdinaryDiffEq.jl heat diffusion step times on one and multiple GPUs.</a></object></p><h2 id="cuNumeric-Kernels-and-Applications" tabindex="-1">cuNumeric Kernels and Applications <a class="header-anchor" href="#cuNumeric-Kernels-and-Applications" aria-label="Permalink to &quot;cuNumeric Kernels and Applications {#cuNumeric-Kernels-and-Applications}&quot;">​</a></h2><p>These benchmarks are written entirely with cuNumeric.jl and compared against cuPyNumeric and other Julia GPU frameworks. Lower times are better.</p><h3 id="Weak-Scaling" tabindex="-1">Weak Scaling <a class="header-anchor" href="#Weak-Scaling" aria-label="Permalink to &quot;Weak Scaling {#Weak-Scaling}&quot;">​</a></h3><p>Time per step on 1–8 GPUs for each benchmark, compared with cuPyNumeric, CUDA.jl, Dagger.jl, and JACC.jl. <object data="../images/benchmarks/grid_time.pdf" type="application/pdf" style="width:100%;aspect-ratio:490 / 551;" aria-label="Weak scaling time per step for GEMM, Monte Carlo, Gray-Scott, HPC-CG, NAS EP, NAS FT, and NAS MG."><a href="../images/benchmarks/grid_time.pdf">Weak scaling time per step for GEMM, Monte Carlo, Gray-Scott, HPC-CG, NAS EP, NAS FT, and NAS MG.</a></object></p><h3 id="Broadcast-Fusion" tabindex="-1">Broadcast Fusion <a class="header-anchor" href="#Broadcast-Fusion" aria-label="Permalink to &quot;Broadcast Fusion {#Broadcast-Fusion}&quot;">​</a></h3><p>Gray-Scott and Monte Carlo with and without broadcast fusion, compared with cuPyNumeric and ImplicitGlobalGrid.jl. <object data="../images/benchmarks/fusion_time.pdf" type="application/pdf" style="width:100%;aspect-ratio:481 / 217;" aria-label="Gray-Scott and Monte Carlo time per step with and without broadcast fusion."><a href="../images/benchmarks/fusion_time.pdf">Gray-Scott and Monte Carlo time per step with and without broadcast fusion.</a></object></p><h3 id="Gray-Scott" tabindex="-1">Gray-Scott <a class="header-anchor" href="#Gray-Scott" aria-label="Permalink to &quot;Gray-Scott {#Gray-Scott}&quot;">​</a></h3><p>Throughput and time per step for the 2D Gray-Scott stencil, compared with cuPyNumeric and ImplicitGlobalGrid.jl. <object data="../images/benchmarks/grayscott_compare.pdf" type="application/pdf" style="width:100%;aspect-ratio:460 / 264;" aria-label="Gray-Scott throughput and time per step on one and multiple GPUs."><a href="../images/benchmarks/grayscott_compare.pdf">Gray-Scott throughput and time per step on one and multiple GPUs.</a></object></p><h3 id="Problem-Size-Sweep" tabindex="-1">Problem Size Sweep <a class="header-anchor" href="#Problem-Size-Sweep" aria-label="Permalink to &quot;Problem Size Sweep {#Problem-Size-Sweep}&quot;">​</a></h3><p>Time per step on one GPU as the problem size grows. At small sizes, fixed per-task runtime overhead dominates and hand-written CUDA.jl kernels are faster. The gap closes as the problem grows. <object data="../images/benchmarks/sweep_time.pdf" type="application/pdf" style="width:100%;aspect-ratio:502 / 201;" aria-label="Gray-Scott and Monte Carlo time per step versus problem size on one GPU."><a href="../images/benchmarks/sweep_time.pdf">Gray-Scott and Monte Carlo time per step versus problem size on one GPU.</a></object></p><h3 id="Code-Complexity-vs-Performance" tabindex="-1">Code Complexity vs Performance <a class="header-anchor" href="#Code-Complexity-vs-Performance" aria-label="Permalink to &quot;Code Complexity vs Performance {#Code-Complexity-vs-Performance}&quot;">​</a></h3><p>Cyclomatic complexity of each implementation against its performance relative to the fastest model on 8 GPUs. Small markers are individual benchmarks and large markers are per-model means. The ideal is the top-left corner. <object data="../images/benchmarks/complexity_8gpu.pdf" type="application/pdf" style="width:100%;aspect-ratio:474 / 213;" aria-label="Cyclomatic complexity versus relative performance on 8 GPUs for cuNumeric.jl, Dagger.jl, and JACC.jl."><a href="../images/benchmarks/complexity_8gpu.pdf">Cyclomatic complexity versus relative performance on 8 GPUs for cuNumeric.jl, Dagger.jl, and JACC.jl.</a></object></p>',17)])])}const u=a(i,[["render",n]]);export{h as __pageData,u as default};
